tool_use_result.content:
/* === VARIABLES === */
:root {
  --primary: #0a0a23;
  --accent: #FEAC32;
  --link: #002EAD;
  --text: #1b1b32;
  --text-light: #6b6b7b;
  --text-muted: #9a9aaa;
  --bg: #ffffff;
  --bg-light: #f5f6f7;
  --bg-dark: #0a0a23;
  --border: #e8e8ec;
  --card-shadow: 0 2px 8px rgba(10,10,35,0.08);
  --card-shadow-hover: 0 8px 28px rgba(10,10,35,0.15);
  --radius: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;
  --font: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --header-h: 64px;
  --max-w: 1200px;
  --transition: 0.2s ease;
}

/* === RESET === */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; scroll-behavior: smooth; }
body {
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { display: block; max-width: 100%; }
a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* === LAYOUT === */
.container {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 48px 0; }
.section--lg { padding: 64px 0; }

/* === HEADER === */
.site-header {
  background: var(--primary);
  height: var(--header-h);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 12px rgba(0,0,0,0.3);
}
.site-header .container {
  display: flex;
  align-items: center;
  height: 100%;
  gap: 20px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--accent);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 18px;
  color: var(--primary);
  letter-spacing: -1px;
}
.logo-text {
  font-size: 17px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: -0.3px;
}
.logo-text span { color: var(--accent); }
.search-bar {
  flex: 1;
  max-width: 480px;
  position: relative;
}
.search-bar input {
  width: 100%;
  height: 38px;
  padding: 0 16px 0 40px;
  border-radius: var(--radius-full);
  border: 1.5px solid rgba(255,255,255,0.15);
  background: rgba(255,255,255,0.08);
  color: #fff;
  font-size: 14px;
  font-family: var(--font);
  outline: none;
  transition: var(--transition);
}
.search-bar input::placeholder { color: rgba(255,255,255,0.45); }
.search-bar input:focus {
  border-color: var(--accent);
  background: rgba(255,255,255,0.12);
}
.search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255,255,255,0.45);
  pointer-events: none;
}
.main-nav {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 6px;
}
.main-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 14px;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius);
  transition: var(--transition);
  text-decoration: none;
}
.main-nav a:hover { color: #fff; background: rgba(255,255,255,0.1); }
.main-nav a.donate-btn {
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  padding: 8px 18px;
}
.main-nav a.donate-btn:hover { background: #ffbe4d; text-decoration: none; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  margin-left: auto;
  border-radius: 6px;
  background: none;
  transition: var(--transition);
}
.hamburger:hover { background: rgba(255,255,255,0.1); }
.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: var(--transition);
}
.hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-h);
  left: 0;
  right: 0;
  background: var(--primary);
  border-top: 1px solid rgba(255,255,255,0.1);
  z-index: 99;
  padding: 16px;
  flex-direction: column;
  gap: 4px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 16px;
  font-weight: 500;
  padding: 12px 16px;
  border-radius: var(--radius);
  text-decoration: none;
  transition: var(--transition);
}
.mobile-nav a:hover { background: rgba(255,255,255,0.1); color: #fff; }
.mobile-nav a.donate-btn {
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  text-align: center;
  margin-top: 8px;
}

/* === BANNER === */
.site-banner {
  background: var(--accent);
  padding: 10px 24px;
  text-align: center;
}
.site-banner a {
  color: var(--primary);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.site-banner a:hover { text-decoration: underline; }

/* === TAG PILLS === */
.tag {
  display: inline-block;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  text-decoration: none;
}
.tag:hover { text-decoration: none; filter: brightness(1.1); }
.tag-ai { background: #ede9fe; color: #5b21b6; }
.tag-scraping { background: #d1fae5; color: #065f46; }
.tag-databases { background: #dbeafe; color: #1e40af; }
.tag-elasticsearch { background: #fee2e2; color: #991b1b; }
.tag-data-eng { background: #e0f2fe; color: #0c4a6e; }
.tag-ai-auto { background: #dcfce7; color: #14532d; }
.tag-python { background: #fef3c7; color: #92400e; }
.tag-nodejs { background: #dcfce7; color: #166534; }
.tag-gsheets { background: #dbeafe; color: #1e3a8a; }
.tag-js { background: #fef9c3; color: #713f12; }
.tag-react { background: #e0f2fe; color: #075985; }
.tag-css { background: #fce7f3; color: #831843; }
.tag-general { background: #f3f4f6; color: #374151; }

/* === ARTICLE THUMBNAILS === */
.thumb {
  width: 100%;
  padding-top: 52%;
  position: relative;
  border-radius: var(--radius) var(--radius) 0 0;
  overflow: hidden;
}
.thumb-inner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.thumb-ai { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%); }
.thumb-scraping { background: linear-gradient(135deg, #134e5e 0%, #71b280 100%); }
.thumb-databases { background: linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%); }
.thumb-elasticsearch { background: linear-gradient(135deg, #833ab4 0%, #fd1d1d 50%, #fcb045 100%); }
.thumb-data-eng { background: linear-gradient(135deg, #4568dc 0%, #b06ab3 100%); }
.thumb-ai-auto { background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%); }
.thumb-python { background: linear-gradient(135deg, #6a11cb 0%, #2575fc 100%); }
.thumb-nodejs { background: linear-gradient(135deg, #56ab2f 0%, #a8e063 100%); }
.thumb-gsheets { background: linear-gradient(135deg, #185a9d 0%, #43cea2 100%); }
.thumb-js { background: linear-gradient(135deg, #f7971e 0%, #ffd200 100%); }
.thumb-react { background: linear-gradient(135deg, #0575e6 0%, #021b79 100%); }
.thumb-css { background: linear-gradient(135deg, #f953c6 0%, #b91d73 100%); }

.thumb-pattern {
  width: 80%;
  height: 80%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  opacity: 0.15;
}
.thumb-pattern span {
  display: block;
  background: #fff;
  border-radius: 3px;
}

/* === FEATURED ARTICLE === */
.featured-section { padding: 32px 0 0; }
.featured-label {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-light);
  margin-bottom: 16px;
}
.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: var(--bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  border: 1px solid var(--border);
  min-height: 320px;
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}
.featured-card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-2px); text-decoration: none; }
.featured-thumb {
  position: relative;
  min-height: 280px;
}
.featured-thumb-bg {
  position: absolute;
  inset: 0;
}
.featured-thumb .tag {
  position: absolute;
  top: 16px;
  left: 16px;
  z-index: 1;
}
.featured-content {
  padding: 32px 36px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
}
.featured-title {
  font-size: 24px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text);
  letter-spacing: -0.3px;
}
.featured-meta { display: flex; align-items: center; gap: 10px; }

/* === AUTHOR === */
.author-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  text-transform: uppercase;
}
.author-info { display: flex; flex-direction: column; }
.author-name { font-size: 13px; font-weight: 600; color: var(--text); }
.author-time { font-size: 12px; color: var(--text-muted); }

/* === ARTICLE GRID === */
.grid-section { padding: 40px 0; }
.grid-section-title {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 28px;
  color: var(--text);
  letter-spacing: -0.3px;
}
.articles-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  background: var(--bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  border: 1px solid var(--border);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
}
.article-card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-3px); text-decoration: none; }
.card-thumb { position: relative; }
.card-thumb .tag {
  position: absolute;
  bottom: 10px;
  left: 10px;
  z-index: 1;
}
.card-body { padding: 16px 18px 20px; flex: 1; display: flex; flex-direction: column; gap: 12px; }
.card-title {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.45;
  color: var(--text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card-meta { display: flex; align-items: center; gap: 8px; margin-top: auto; }
.card-author-name { font-size: 13px; font-weight: 600; color: var(--text); }
.card-time { font-size: 12px; color: var(--text-muted); }

/* === LOAD MORE === */
.load-more-wrap {
  text-align: center;
  padding: 40px 0 20px;
}
.btn-load-more {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--primary);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  padding: 14px 32px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font);
}
.btn-load-more:hover { background: #1a1a40; transform: translateY(-1px); }
.btn-load-more:disabled { opacity: 0.5; cursor: default; transform: none; }

/* === CURRICULUM PAGE === */
.learn-hero {
  background: var(--primary);
  padding: 48px 0;
  color: #fff;
}
.learn-hero h1 {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 12px;
  letter-spacing: -0.5px;
}
.learn-hero p { font-size: 16px; color: rgba(255,255,255,0.75); max-width: 560px; }
.learn-hero .btn-signin {
  display: inline-block;
  margin-top: 20px;
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-size: 15px;
  text-decoration: none;
  transition: var(--transition);
}
.learn-hero .btn-signin:hover { background: #ffbe4d; text-decoration: none; }

.curriculum-section { padding: 48px 0; }
.curriculum-section h2 {
  font-size: 26px;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.3px;
}
.curriculum-section .section-sub {
  font-size: 15px;
  color: var(--text-light);
  margin-bottom: 32px;
}
.cert-list { display: flex; flex-direction: column; gap: 12px; }
.cert-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 22px;
  background: var(--bg);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-lg);
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
  color: var(--text);
}
.cert-item:hover { border-color: var(--accent); box-shadow: var(--card-shadow-hover); transform: translateX(4px); text-decoration: none; }
.cert-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  flex-shrink: 0;
}
.cert-info { flex: 1; }
.cert-title { font-size: 16px; font-weight: 600; color: var(--text); }
.cert-meta { font-size: 13px; color: var(--text-light); margin-top: 2px; }
.cert-arrow { color: var(--text-muted); font-size: 18px; }

.challenge-box {
  background: linear-gradient(135deg, var(--primary) 0%, #1a1a4e 100%);
  border-radius: var(--radius-lg);
  padding: 36px 40px;
  color: #fff;
  margin-bottom: 48px;
}
.challenge-box h2 { font-size: 24px; font-weight: 700; margin-bottom: 10px; }
.challenge-box p { color: rgba(255,255,255,0.75); margin-bottom: 24px; font-size: 15px; }
.challenge-links { display: flex; gap: 12px; flex-wrap: wrap; }
.btn-challenge {
  padding: 10px 22px;
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: var(--transition);
}
.btn-challenge.primary { background: var(--accent); color: var(--primary); }
.btn-challenge.primary:hover { background: #ffbe4d; text-decoration: none; }
.btn-challenge.secondary { background: rgba(255,255,255,0.1); color: #fff; border: 1.5px solid rgba(255,255,255,0.25); }
.btn-challenge.secondary:hover { background: rgba(255,255,255,0.18); text-decoration: none; }

.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}
.resource-card {
  background: var(--bg-light);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.resource-card h3 { font-size: 16px; font-weight: 700; margin-bottom: 14px; color: var(--text); }
.resource-link {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
  color: var(--link);
  text-decoration: none;
  transition: var(--transition);
}
.resource-link:last-child { border-bottom: none; }
.resource-link:hover { color: var(--primary); text-decoration: underline; }
.resource-link::before { content: '→'; font-size: 12px; color: var(--accent); }

/* === DONATE PAGE === */
.donate-hero {
  background: var(--primary);
  padding: 64px 0;
  color: #fff;
  text-align: center;
}
.donate-hero h1 {
  font-size: 40px;
  font-weight: 800;
  margin-bottom: 16px;
  letter-spacing: -0.8px;
}
.donate-hero p {
  font-size: 17px;
  color: rgba(255,255,255,0.75);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.donation-form-section { padding: 48px 0; }
.donation-card {
  max-width: 540px;
  margin: 0 auto;
  background: var(--bg);
  border-radius: var(--radius-lg);
  box-shadow: 0 8px 40px rgba(10,10,35,0.12);
  border: 1px solid var(--border);
  overflow: hidden;
}
.donation-card-header {
  background: var(--primary);
  padding: 24px 32px;
  color: #fff;
}
.donation-card-header h2 { font-size: 22px; font-weight: 700; }
.donation-card-header p { font-size: 14px; color: rgba(255,255,255,0.65); margin-top: 4px; }
.donation-card-body { padding: 28px 32px; }

.amount-tabs {
  display: flex;
  gap: 10px;
  margin-bottom: 24px;
}
.amount-btn {
  flex: 1;
  padding: 12px 8px;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
  background: var(--bg);
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font);
}
.amount-btn:hover { border-color: var(--accent); }
.amount-btn.active {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--primary);
}

.donation-desc {
  background: var(--bg-light);
  border-radius: var(--radius);
  padding: 14px 18px;
  font-size: 14px;
  color: var(--text);
  margin-bottom: 24px;
  border-left: 3px solid var(--accent);
  min-height: 52px;
  transition: var(--transition);
}

.btn-donate {
  display: block;
  width: 100%;
  padding: 16px;
  background: var(--accent);
  color: var(--primary);
  font-size: 17px;
  font-weight: 800;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  font-family: var(--font);
  transition: var(--transition);
  letter-spacing: -0.2px;
}
.btn-donate:hover { background: #ffbe4d; transform: translateY(-1px); }
.donate-sublabel {
  text-align: center;
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 12px;
}
.donate-sublabel a { color: var(--link); }

.benefits-section { background: var(--bg-light); padding: 56px 0; }
.benefits-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 32px;
  letter-spacing: -0.3px;
}
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
}
.benefit-icon { font-size: 24px; flex-shrink: 0; }
.benefit-text { font-size: 15px; color: var(--text); line-height: 1.5; }

.initiatives-section { padding: 56px 0; }
.initiatives-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 32px;
  letter-spacing: -0.3px;
}
.initiatives-list { display: flex; flex-direction: column; gap: 12px; }
.initiative-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 18px 22px;
  background: var(--bg-light);
  border-radius: var(--radius);
}
.initiative-bullet {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
  margin-top: 6px;
}
.initiative-text { font-size: 15px; color: var(--text); }

.stats-section { background: var(--primary); padding: 56px 0; color: #fff; }
.stats-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 40px;
  letter-spacing: -0.3px;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.stat-item {
  background: rgba(255,255,255,0.07);
  border-radius: var(--radius-lg);
  padding: 24px;
  border: 1px solid rgba(255,255,255,0.1);
}
.stat-number {
  font-size: 36px;
  font-weight: 800;
  color: var(--accent);
  letter-spacing: -1px;
  margin-bottom: 6px;
}
.stat-label { font-size: 14px; color: rgba(255,255,255,0.7); line-height: 1.4; }

/* === FAQ ACCORDION === */
.faq-section { padding: 56px 0; background: var(--bg-light); }
.faq-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 32px;
  letter-spacing: -0.3px;
}
.faq-list { display: flex; flex-direction: column; gap: 8px; max-width: 800px; }
.faq-item {
  background: var(--bg);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: var(--transition);
}
.faq-item.open { border-color: var(--accent); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  cursor: pointer;
  gap: 16px;
  background: none;
  width: 100%;
  text-align: left;
  font-family: var(--font);
}
.faq-question-text {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  line-height: 1.4;
}
.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text);
  font-size: 18px;
  flex-shrink: 0;
  transition: var(--transition);
  font-weight: 300;
}
.faq-item.open .faq-icon { background: var(--accent); color: var(--primary); transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-answer-inner { padding: 0 20px 18px; font-size: 14px; color: var(--text-light); line-height: 1.7; }
.faq-item.open .faq-answer { max-height: 400px; }

/* === TAG PAGE === */
.tag-header { padding: 40px 0 24px; }
.tag-title {
  display: flex;
  align-items: baseline;
  gap: 16px;
  flex-wrap: wrap;
}
.tag-title h1 {
  font-size: 36px;
  font-weight: 800;
  color: var(--text);
  letter-spacing: -0.8px;
}
.tag-count {
  font-size: 16px;
  color: var(--text-light);
  font-weight: 400;
}

.popular-tags-section { padding: 16px 0 32px; }
.popular-tags-label {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--text-muted);
  margin-bottom: 12px;
}
.popular-tags-scroll {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 8px;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}
.popular-tags-scroll::-webkit-scrollbar { height: 4px; }
.popular-tags-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
.popular-tag-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  background: var(--bg-light);
  border: 1.5px solid var(--border);
  white-space: nowrap;
  text-decoration: none;
  transition: var(--transition);
  flex-shrink: 0;
}
.popular-tag-item:hover { border-color: var(--primary); background: var(--primary); text-decoration: none; }
.popular-tag-item:hover .ptag-name,
.popular-tag-item:hover .ptag-count { color: #fff; }
.ptag-name { font-size: 13px; font-weight: 600; color: var(--text); }
.ptag-count { font-size: 12px; color: var(--text-muted); }

/* === FOOTER === */
.site-footer {
  background: var(--primary);
  color: rgba(255,255,255,0.7);
  padding: 48px 0 32px;
}
.footer-mission {
  font-size: 14px;
  line-height: 1.7;
  max-width: 640px;
  margin-bottom: 36px;
  border-left: 3px solid var(--accent);
  padding-left: 16px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  margin-bottom: 36px;
}
.footer-col h3 {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: rgba(255,255,255,0.45);
  margin-bottom: 14px;
}
.footer-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.footer-tag {
  color: rgba(255,255,255,0.65);
  font-size: 13px;
  text-decoration: none;
  transition: var(--transition);
}
.footer-tag:hover { color: var(--accent); text-decoration: none; }
.footer-tag::after { content: ' ·'; margin-right: 2px; }
.footer-tag:last-child::after { content: ''; }
.footer-links { display: flex; flex-wrap: wrap; gap: 6px; }
.footer-links a {
  color: rgba(255,255,255,0.65);
  font-size: 13px;
  text-decoration: none;
  transition: var(--transition);
}
.footer-links a:hover { color: rgba(255,255,255,0.9); text-decoration: underline; }
.footer-links a::after { content: ' ·'; margin-right: 2px; }
.footer-links a:last-child::after { content: ''; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}
.footer-logo { display: flex; align-items: center; gap: 8px; text-decoration: none; }
.footer-logo .logo-icon { width: 28px; height: 28px; font-size: 14px; }
.footer-logo .logo-text { font-size: 15px; }
.footer-copy { font-size: 13px; }

/* === UTILITIES === */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

/* === RESPONSIVE === */
@media (max-width: 900px) {
  .articles-grid { grid-template-columns: repeat(2, 1fr); }
  .resources-grid { grid-template-columns: 1fr 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 220px; }
  .featured-title { font-size: 20px; }
  .footer-grid { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  :root { --header-h: 56px; }
  .container { padding: 0 16px; }
  .search-bar { display: none; }
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .articles-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .challenge-links { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .donate-hero h1 { font-size: 28px; }
  .learn-hero h1 { font-size: 24px; }
  .featured-content { padding: 20px; }
  .donation-card-body { padding: 20px; }
  .donation-card-header { padding: 18px 20px; }
  .amount-tabs { gap: 6px; }
  .amount-btn { font-size: 16px; }
  .tag-title h1 { font-size: 26px; }
}

/* === VARIABLES === */
:root {
  --primary: #0a0a23;
  --accent: #FEAC32;
  --link: #002EAD;
  --text: #1b1b32;
  --text-light: #6b6b7b;
  --text-muted: #9a9aaa;
  --bg: #ffffff;
  --bg-light: #f5f6f7;
  --bg-dark: #0a0a23;
  --border: #e8e8ec;
  --card-shadow: 0 2px 8px rgba(10,10,35,0.08);
  --card-shadow-hover: 0 8px 28px rgba(10,10,35,0.15);
  --radius: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;
  --font: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --header-h: 64px;
  --max-w: 1200px;
  --transition: 0.2s ease;
}

/* === RESET === */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; scroll-behavior: smooth; }
body {
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { display: block; max-width: 100%; }
a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* === LAYOUT === */
.container {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 48px 0; }
.section--lg { padding: 64px 0; }

/* === HEADER === */
.site-header {
  background: var(--primary);
  height: var(--header-h);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 12px rgba(0,0,0,0.3);
}
.site-header .container {
  display: flex;
  align-items: center;
  height: 100%;
  gap: 20px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--accent);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 18px;
  color: var(--primary);
  letter-spacing: -1px;
}
.logo-text {
  font-size: 17px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: -0.3px;
}
.logo-text span { color: var(--accent); }
.search-bar {
  flex: 1;
  max-width: 480px;
  position: relative;
}
.search-bar input {
  width: 100%;
  height: 38px;
  padding: 0 16px 0 40px;
  border-radius: var(--radius-full);
  border: 1.5px solid rgba(255,255,255,0.15);
  background: rgba(255,255,255,0.08);
  color: #fff;
  font-size: 14px;
  font-family: var(--font);
  outline: none;
  transition: var(--transition);
}
.search-bar input::placeholder { color: rgba(255,255,255,0.45); }
.search-bar input:focus {
  border-color: var(--accent);
  background: rgba(255,255,255,0.12);
}
.search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255,255,255,0.45);
  pointer-events: none;
}
.main-nav {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 6px;
}
.main-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 14px;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius);
  transition: var(--transition);
  text-decoration: none;
}
.main-nav a:hover { color: #fff; background: rgba(255,255,255,0.1); }
.main-nav a.donate-btn {
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  padding: 8px 18px;
}
.main-nav a.donate-btn:hover { background: #ffbe4d; text-decoration: none; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  margin-left: auto;
  border-radius: 6px;
  background: none;
  transition: var(--transition);
}
.hamburger:hover { background: rgba(255,255,255,0.1); }
.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: var(--transition);
}
.hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-h);
  left: 0;
  right: 0;
  background: var(--primary);
  border-top: 1px solid rgba(255,255,255,0.1);
  z-index: 99;
  padding: 16px;
  flex-direction: column;
  gap: 4px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 16px;
  font-weight: 500;
  padding: 12px 16px;
  border-radius: var(--radius);
  text-decoration: none;
  transition: var(--transition);
}
.mobile-nav a:hover { background: rgba(255,255,255,0.1); color: #fff; }
.mobile-nav a.donate-btn {
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  text-align: center;
  margin-top: 8px;
}

/* === BANNER === */
.site-banner {
  background: var(--accent);
  padding: 10px 24px;
  text-align: center;
}
.site-banner a {
  color: var(--primary);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.site-banner a:hover { text-decoration: underline; }

/* === TAG PILLS === */
.tag {
  display: inline-block;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  text-decoration: none;
}
.tag:hover { text-decoration: none; filter: brightness(1.1); }
.tag-ai { background: #ede9fe; color: #5b21b6; }
.tag-scraping { background: #d1fae5; color: #065f46; }
.tag-databases { background: #dbeafe; color: #1e40af; }
.tag-elasticsearch { background: #fee2e2; color: #991b1b; }
.tag-data-eng { background: #e0f2fe; color: #0c4a6e; }
.tag-ai-auto { background: #dcfce7; color: #14532d; }
.tag-python { background: #fef3c7; color: #92400e; }
.tag-nodejs { background: #dcfce7; color: #166534; }
.tag-gsheets { background: #dbeafe; color: #1e3a8a; }
.tag-js { background: #fef9c3; color: #713f12; }
.tag-react { background: #e0f2fe; color: #075985; }
.tag-css { background: #fce7f3; color: #831843; }
.tag-general { background: #f3f4f6; color: #374151; }

/* === ARTICLE THUMBNAILS === */
.thumb {
  width: 100%;
  padding-top: 52%;
  position: relative;
  border-radius: var(--radius) var(--radius) 0 0;
  overflow: hidden;
}
.thumb-inner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.thumb-ai { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%); }
.thumb-scraping { background: linear-gradient(135deg, #134e5e 0%, #71b280 100%); }
.thumb-databases { background: linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%); }
.thumb-elasticsearch { background: linear-gradient(135deg, #833ab4 0%, #fd1d1d 50%, #fcb045 100%); }
.thumb-data-eng { background: linear-gradient(135deg, #4568dc 0%, #b06ab3 100%); }
.thumb-ai-auto { background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%); }
.thumb-python { background: linear-gradient(135deg, #6a11cb 0%, #2575fc 100%); }
.thumb-nodejs { background: linear-gradient(135deg, #56ab2f 0%, #a8e063 100%); }
.thumb-gsheets { background: linear-gradient(135deg, #185a9d 0%, #43cea2 100%); }
.thumb-js { background: linear-gradient(135deg, #f7971e 0%, #ffd200 100%); }
.thumb-react { background: linear-gradient(135deg, #0575e6 0%, #021b79 100%); }
.thumb-css { background: linear-gradient(135deg, #f953c6 0%, #b91d73 100%); }

.thumb-pattern {
  width: 80%;
  height: 80%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  opacity: 0.15;
}
.thumb-pattern span {
  display: block;
  background: #fff;
  border-radius: 3px;
}

/* === FEATURED ARTICLE === */
.featured-section { padding: 32px 0 0; }
.featured-label {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-light);
  margin-bottom: 16px;
}
.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: var(--bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  border: 1px solid var(--border);
  min-height: 320px;
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}
.featured-card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-2px); text-decoration: none; }
.featured-thumb {
  position: relative;
  min-height: 280px;
}
.featured-thumb-bg {
  position: absolute;
  inset: 0;
}
.featured-thumb .tag {
  position: absolute;
  top: 16px;
  left: 16px;
  z-index: 1;
}
.featured-content {
  padding: 32px 36px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
}
.featured-title {
  font-size: 24px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text);
  letter-spacing: -0.3px;
}
.featured-meta { display: flex; align-items: center; gap: 10px; }

/* === AUTHOR === */
.author-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  text-transform: uppercase;
}
.author-info { display: flex; flex-direction: column; }
.author-name { font-size: 13px; font-weight: 600; color: var(--text); }
.author-time { font-size: 12px; color: var(--text-muted); }

/* === ARTICLE GRID === */
.grid-section { padding: 40px 0; }
.grid-section-title {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 28px;
  color: var(--text);
  letter-spacing: -0.3px;
}
.articles-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  background: var(--bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  border: 1px solid var(--border);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
}
.article-card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-3px); text-decoration: none; }
.card-thumb { position: relative; }
.card-thumb .tag {
  position: absolute;
  bottom: 10px;
  left: 10px;
  z-index: 1;
}
.card-body { padding: 16px 18px 20px; flex: 1; display: flex; flex-direction: column; gap: 12px; }
.card-title {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.45;
  color: var(--text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card-meta { display: flex; align-items: center; gap: 8px; margin-top: auto; }
.card-author-name { font-size: 13px; font-weight: 600; color: var(--text); }
.card-time { font-size: 12px; color: var(--text-muted); }

/* === LOAD MORE === */
.load-more-wrap {
  text-align: center;
  padding: 40px 0 20px;
}
.btn-load-more {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--primary);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  padding: 14px 32px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font);
}
.btn-load-more:hover { background: #1a1a40; transform: translateY(-1px); }
.btn-load-more:disabled { opacity: 0.5; cursor: default; transform: none; }

/* === CURRICULUM PAGE === */
.learn-hero {
  background: var(--primary);
  padding: 48px 0;
  color: #fff;
}
.learn-hero h1 {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 12px;
  letter-spacing: -0.5px;
}
.learn-hero p { font-size: 16px; color: rgba(255,255,255,0.75); max-width: 560px; }
.learn-hero .btn-signin {
  display: inline-block;
  margin-top: 20px;
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-size: 15px;
  text-decoration: none;
  transition: var(--transition);
}
.learn-hero .btn-signin:hover { background: #ffbe4d; text-decoration: none; }

.curriculum-section { padding: 48px 0; }
.curriculum-section h2 {
  font-size: 26px;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.3px;
}
.curriculum-section .section-sub {
  font-size: 15px;
  color: var(--text-light);
  margin-bottom: 32px;
}
.cert-list { display: flex; flex-direction: column; gap: 12px; }
.cert-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 22px;
  background: var(--bg);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-lg);
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
  color: var(--text);
}
.cert-item:hover { border-color: var(--accent); box-shadow: var(--card-shadow-hover); transform: translateX(4px); text-decoration: none; }
.cert-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  flex-shrink: 0;
}
.cert-info { flex: 1; }
.cert-title { font-size: 16px; font-weight: 600; color: var(--text); }
.cert-meta { font-size: 13px; color: var(--text-light); margin-top: 2px; }
.cert-arrow { color: var(--text-muted); font-size: 18px; }

.challenge-box {
  background: linear-gradient(135deg, var(--primary) 0%, #1a1a4e 100%);
  border-radius: var(--radius-lg);
  padding: 36px 40px;
  color: #fff;
  margin-bottom: 48px;
}
.challenge-box h2 { font-size: 24px; font-weight: 700; margin-bottom: 10px; }
.challenge-box p { color: rgba(255,255,255,0.75); margin-bottom: 24px; font-size: 15px; }
.challenge-links { display: flex; gap: 12px; flex-wrap: wrap; }
.btn-challenge {
  padding: 10px 22px;
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: var(--transition);
}
.btn-challenge.primary { background: var(--accent); color: var(--primary); }
.btn-challenge.primary:hover { background: #ffbe4d; text-decoration: none; }
.btn-challenge.secondary { background: rgba(255,255,255,0.1); color: #fff; border: 1.5px solid rgba(255,255,255,0.25); }
.btn-challenge.secondary:hover { background: rgba(255,255,255,0.18); text-decoration: none; }

.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}
.resource-card {
  background: var(--bg-light);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.resource-card h3 { font-size: 16px; font-weight: 700; margin-bottom: 14px; color: var(--text); }
.resource-link {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
  color: var(--link);
  text-decoration: none;
  transition: var(--transition);
}
.resource-link:last-child { border-bottom: none; }
.resource-link:hover { color: var(--primary); text-decoration: underline; }
.resource-link::before { content: '→'; font-size: 12px; color: var(--accent); }

/* === DONATE PAGE === */
.donate-hero {
  background: var(--primary);
  padding: 64px 0;
  color: #fff;
  text-align: center;
}
.donate-hero h1 {
  font-size: 40px;
  font-weight: 800;
  margin-bottom: 16px;
  letter-spacing: -0.8px;
}
.donate-hero p {
  font-size: 17px;
  color: rgba(255,255,255,0.75);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.donation-form-section { padding: 48px 0; }
.donation-card {
  max-width: 540px;
  margin: 0 auto;
  background: var(--bg);
  border-radius: var(--radius-lg);
  box-shadow: 0 8px 40px rgba(10,10,35,0.12);
  border: 1px solid var(--border);
  overflow: hidden;
}
.donation-card-header {
  background: var(--primary);
  padding: 24px 32px;
  color: #fff;
}
.donation-card-header h2 { font-size: 22px; font-weight: 700; }
.donation-card-header p { font-size: 14px; color: rgba(255,255,255,0.65); margin-top: 4px; }
.donation-card-body { padding: 28px 32px; }

.amount-tabs {
  display: flex;
  gap: 10px;
  margin-bottom: 24px;
}
.amount-btn {
  flex: 1;
  padding: 12px 8px;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
  background: var(--bg);
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font);
}
.amount-btn:hover { border-color: var(--accent); }
.amount-btn.active {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--primary);
}

.donation-desc {
  background: var(--bg-light);
  border-radius: var(--radius);
  padding: 14px 18px;
  font-size: 14px;
  color: var(--text);
  margin-bottom: 24px;
  border-left: 3px solid var(--accent);
  min-height: 52px;
  transition: var(--transition);
}

.btn-donate {
  display: block;
  width: 100%;
  padding: 16px;
  background: var(--accent);
  color: var(--primary);
  font-size: 17px;
  font-weight: 800;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  font-family: var(--font);
  transition: var(--transition);
  letter-spacing: -0.2px;
}
.btn-donate:hover { background: #ffbe4d; transform: translateY(-1px); }
.donate-sublabel {
  text-align: center;
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 12px;
}
.donate-sublabel a { color: var(--link); }

.benefits-section { background: var(--bg-light); padding: 56px 0; }
.benefits-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 32px;
  letter-spacing: -0.3px;
}
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
}
.benefit-icon { font-size: 24px; flex-shrink: 0; }
.benefit-text { font-size: 15px; color: var(--text); line-height: 1.5; }

.initiatives-section { padding: 56px 0; }
.initiatives-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 32px;
  letter-spacing: -0.3px;
}
.initiatives-list { display: flex; flex-direction: column; gap: 12px; }
.initiative-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 18px 22px;
  background: var(--bg-light);
  border-radius: var(--radius);
}
.initiative-bullet {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
  margin-top: 6px;
}
.initiative-text { font-size: 15px; color: var(--text); }

.stats-section { background: var(--primary); padding: 56px 0; color: #fff; }
.stats-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 40px;
  letter-spacing: -0.3px;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.stat-item {
  background: rgba(255,255,255,0.07);
  border-radius: var(--radius-lg);
  padding: 24px;
  border: 1px solid rgba(255,255,255,0.1);
}
.stat-number {
  font-size: 36px;
  font-weight: 800;
  color: var(--accent);
  letter-spacing: -1px;
  margin-bottom: 6px;
}
.stat-label { font-size: 14px; color: rgba(255,255,255,0.7); line-height: 1.4; }

/* === FAQ ACCORDION === */
.faq-section { padding: 56px 0; background: var(--bg-light); }
.faq-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 32px;
  letter-spacing: -0.3px;
}
.faq-list { display: flex; flex-direction: column; gap: 8px; max-width: 800px; }
.faq-item {
  background: var(--bg);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: var(--transition);
}
.faq-item.open { border-color: var(--accent); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  cursor: pointer;
  gap: 16px;
  background: none;
  width: 100%;
  text-align: left;
  font-family: var(--font);
}
.faq-question-text {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  line-height: 1.4;
}
.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text);
  font-size: 18px;
  flex-shrink: 0;
  transition: var(--transition);
  font-weight: 300;
}
.faq-item.open .faq-icon { background: var(--accent); color: var(--primary); transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-answer-inner { padding: 0 20px 18px; font-size: 14px; color: var(--text-light); line-height: 1.7; }
.faq-item.open .faq-answer { max-height: 400px; }

/* === TAG PAGE === */
.tag-header { padding: 40px 0 24px; }
.tag-title {
  display: flex;
  align-items: baseline;
  gap: 16px;
  flex-wrap: wrap;
}
.tag-title h1 {
  font-size: 36px;
  font-weight: 800;
  color: var(--text);
  letter-spacing: -0.8px;
}
.tag-count {
  font-size: 16px;
  color: var(--text-light);
  font-weight: 400;
}

.popular-tags-section { padding: 16px 0 32px; }
.popular-tags-label {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--text-muted);
  margin-bottom: 12px;
}
.popular-tags-scroll {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 8px;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}
.popular-tags-scroll::-webkit-scrollbar { height: 4px; }
.popular-tags-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
.popular-tag-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  background: var(--bg-light);
  border: 1.5px solid var(--border);
  white-space: nowrap;
  text-decoration: none;
  transition: var(--transition);
  flex-shrink: 0;
}
.popular-tag-item:hover { border-color: var(--primary); background: var(--primary); text-decoration: none; }
.popular-tag-item:hover .ptag-name,
.popular-tag-item:hover .ptag-count { color: #fff; }
.ptag-name { font-size: 13px; font-weight: 600; color: var(--text); }
.ptag-count { font-size: 12px; color: var(--text-muted); }

/* === FOOTER === */
.site-footer {
  background: var(--primary);
  color: rgba(255,255,255,0.7);
  padding: 48px 0 32px;
}
.footer-mission {
  font-size: 14px;
  line-height: 1.7;
  max-width: 640px;
  margin-bottom: 36px;
  border-left: 3px solid var(--accent);
  padding-left: 16px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  margin-bottom: 36px;
}
.footer-col h3 {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: rgba(255,255,255,0.45);
  margin-bottom: 14px;
}
.footer-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.footer-tag {
  color: rgba(255,255,255,0.65);
  font-size: 13px;
  text-decoration: none;
  transition: var(--transition);
}
.footer-tag:hover { color: var(--accent); text-decoration: none; }
.footer-tag::after { content: ' ·'; margin-right: 2px; }
.footer-tag:last-child::after { content: ''; }
.footer-links { display: flex; flex-wrap: wrap; gap: 6px; }
.footer-links a {
  color: rgba(255,255,255,0.65);
  font-size: 13px;
  text-decoration: none;
  transition: var(--transition);
}
.footer-links a:hover { color: rgba(255,255,255,0.9); text-decoration: underline; }
.footer-links a::after { content: ' ·'; margin-right: 2px; }
.footer-links a:last-child::after { content: ''; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}
.footer-logo { display: flex; align-items: center; gap: 8px; text-decoration: none; }
.footer-logo .logo-icon { width: 28px; height: 28px; font-size: 14px; }
.footer-logo .logo-text { font-size: 15px; }
.footer-copy { font-size: 13px; }

/* === UTILITIES === */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

/* === RESPONSIVE === */
@media (max-width: 900px) {
  .articles-grid { grid-template-columns: repeat(2, 1fr); }
  .resources-grid { grid-template-columns: 1fr 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 220px; }
  .featured-title { font-size: 20px; }
  .footer-grid { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  :root { --header-h: 56px; }
  .container { padding: 0 16px; }
  .search-bar { display: none; }
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .articles-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .challenge-links { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .donate-hero h1 { font-size: 28px; }
  .learn-hero h1 { font-size: 24px; }
  .featured-content { padding: 20px; }
  .donation-card-body { padding: 20px; }
  .donation-card-header { padding: 18px 20px; }
  .amount-tabs { gap: 6px; }
  .amount-btn { font-size: 16px; }
  .tag-title h1 { font-size: 26px; }
}

raw_arguments.content:
/* === VARIABLES === */
:root {
  --primary: #0a0a23;
  --accent: #FEAC32;
  --link: #002EAD;
  --text: #1b1b32;
  --text-light: #6b6b7b;
  --text-muted: #9a9aaa;
  --bg: #ffffff;
  --bg-light: #f5f6f7;
  --bg-dark: #0a0a23;
  --border: #e8e8ec;
  --card-shadow: 0 2px 8px rgba(10,10,35,0.08);
  --card-shadow-hover: 0 8px 28px rgba(10,10,35,0.15);
  --radius: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;
  --font: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --header-h: 64px;
  --max-w: 1200px;
  --transition: 0.2s ease;
}

/* === RESET === */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; scroll-behavior: smooth; }
body {
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { display: block; max-width: 100%; }
a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* === LAYOUT === */
.container {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 48px 0; }
.section--lg { padding: 64px 0; }

/* === HEADER === */
.site-header {
  background: var(--primary);
  height: var(--header-h);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 12px rgba(0,0,0,0.3);
}
.site-header .container {
  display: flex;
  align-items: center;
  height: 100%;
  gap: 20px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--accent);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 18px;
  color: var(--primary);
  letter-spacing: -1px;
}
.logo-text {
  font-size: 17px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: -0.3px;
}
.logo-text span { color: var(--accent); }
.search-bar {
  flex: 1;
  max-width: 480px;
  position: relative;
}
.search-bar input {
  width: 100%;
  height: 38px;
  padding: 0 16px 0 40px;
  border-radius: var(--radius-full);
  border: 1.5px solid rgba(255,255,255,0.15);
  background: rgba(255,255,255,0.08);
  color: #fff;
  font-size: 14px;
  font-family: var(--font);
  outline: none;
  transition: var(--transition);
}
.search-bar input::placeholder { color: rgba(255,255,255,0.45); }
.search-bar input:focus {
  border-color: var(--accent);
  background: rgba(255,255,255,0.12);
}
.search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255,255,255,0.45);
  pointer-events: none;
}
.main-nav {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 6px;
}
.main-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 14px;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius);
  transition: var(--transition);
  text-decoration: none;
}
.main-nav a:hover { color: #fff; background: rgba(255,255,255,0.1); }
.main-nav a.donate-btn {
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  padding: 8px 18px;
}
.main-nav a.donate-btn:hover { background: #ffbe4d; text-decoration: none; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  margin-left: auto;
  border-radius: 6px;
  background: none;
  transition: var(--transition);
}
.hamburger:hover { background: rgba(255,255,255,0.1); }
.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: var(--transition);
}
.hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-h);
  left: 0;
  right: 0;
  background: var(--primary);
  border-top: 1px solid rgba(255,255,255,0.1);
  z-index: 99;
  padding: 16px;
  flex-direction: column;
  gap: 4px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 16px;
  font-weight: 500;
  padding: 12px 16px;
  border-radius: var(--radius);
  text-decoration: none;
  transition: var(--transition);
}
.mobile-nav a:hover { background: rgba(255,255,255,0.1); color: #fff; }
.mobile-nav a.donate-btn {
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  text-align: center;
  margin-top: 8px;
}

/* === BANNER === */
.site-banner {
  background: var(--accent);
  padding: 10px 24px;
  text-align: center;
}
.site-banner a {
  color: var(--primary);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.site-banner a:hover { text-decoration: underline; }

/* === TAG PILLS === */
.tag {
  display: inline-block;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  text-decoration: none;
}
.tag:hover { text-decoration: none; filter: brightness(1.1); }
.tag-ai { background: #ede9fe; color: #5b21b6; }
.tag-scraping { background: #d1fae5; color: #065f46; }
.tag-databases { background: #dbeafe; color: #1e40af; }
.tag-elasticsearch { background: #fee2e2; color: #991b1b; }
.tag-data-eng { background: #e0f2fe; color: #0c4a6e; }
.tag-ai-auto { background: #dcfce7; color: #14532d; }
.tag-python { background: #fef3c7; color: #92400e; }
.tag-nodejs { background: #dcfce7; color: #166534; }
.tag-gsheets { background: #dbeafe; color: #1e3a8a; }
.tag-js { background: #fef9c3; color: #713f12; }
.tag-react { background: #e0f2fe; color: #075985; }
.tag-css { background: #fce7f3; color: #831843; }
.tag-general { background: #f3f4f6; color: #374151; }

/* === ARTICLE THUMBNAILS === */
.thumb {
  width: 100%;
  padding-top: 52%;
  position: relative;
  border-radius: var(--radius) var(--radius) 0 0;
  overflow: hidden;
}
.thumb-inner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.thumb-ai { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%); }
.thumb-scraping { background: linear-gradient(135deg, #134e5e 0%, #71b280 100%); }
.thumb-databases { background: linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%); }
.thumb-elasticsearch { background: linear-gradient(135deg, #833ab4 0%, #fd1d1d 50%, #fcb045 100%); }
.thumb-data-eng { background: linear-gradient(135deg, #4568dc 0%, #b06ab3 100%); }
.thumb-ai-auto { background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%); }
.thumb-python { background: linear-gradient(135deg, #6a11cb 0%, #2575fc 100%); }
.thumb-nodejs { background: linear-gradient(135deg, #56ab2f 0%, #a8e063 100%); }
.thumb-gsheets { background: linear-gradient(135deg, #185a9d 0%, #43cea2 100%); }
.thumb-js { background: linear-gradient(135deg, #f7971e 0%, #ffd200 100%); }
.thumb-react { background: linear-gradient(135deg, #0575e6 0%, #021b79 100%); }
.thumb-css { background: linear-gradient(135deg, #f953c6 0%, #b91d73 100%); }

.thumb-pattern {
  width: 80%;
  height: 80%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  opacity: 0.15;
}
.thumb-pattern span {
  display: block;
  background: #fff;
  border-radius: 3px;
}

/* === FEATURED ARTICLE === */
.featured-section { padding: 32px 0 0; }
.featured-label {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-light);
  margin-bottom: 16px;
}
.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: var(--bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  border: 1px solid var(--border);
  min-height: 320px;
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}
.featured-card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-2px); text-decoration: none; }
.featured-thumb {
  position: relative;
  min-height: 280px;
}
.featured-thumb-bg {
  position: absolute;
  inset: 0;
}
.featured-thumb .tag {
  position: absolute;
  top: 16px;
  left: 16px;
  z-index: 1;
}
.featured-content {
  padding: 32px 36px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
}
.featured-title {
  font-size: 24px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text);
  letter-spacing: -0.3px;
}
.featured-meta { display: flex; align-items: center; gap: 10px; }

/* === AUTHOR === */
.author-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  text-transform: uppercase;
}
.author-info { display: flex; flex-direction: column; }
.author-name { font-size: 13px; font-weight: 600; color: var(--text); }
.author-time { font-size: 12px; color: var(--text-muted); }

/* === ARTICLE GRID === */
.grid-section { padding: 40px 0; }
.grid-section-title {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 28px;
  color: var(--text);
  letter-spacing: -0.3px;
}
.articles-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  background: var(--bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  border: 1px solid var(--border);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
}
.article-card:hover { box-shadow: var(--card-shadow-hover); transform: translateY(-3px); text-decoration: none; }
.card-thumb { position: relative; }
.card-thumb .tag {
  position: absolute;
  bottom: 10px;
  left: 10px;
  z-index: 1;
}
.card-body { padding: 16px 18px 20px; flex: 1; display: flex; flex-direction: column; gap: 12px; }
.card-title {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.45;
  color: var(--text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card-meta { display: flex; align-items: center; gap: 8px; margin-top: auto; }
.card-author-name { font-size: 13px; font-weight: 600; color: var(--text); }
.card-time { font-size: 12px; color: var(--text-muted); }

/* === LOAD MORE === */
.load-more-wrap {
  text-align: center;
  padding: 40px 0 20px;
}
.btn-load-more {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--primary);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  padding: 14px 32px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font);
}
.btn-load-more:hover { background: #1a1a40; transform: translateY(-1px); }
.btn-load-more:disabled { opacity: 0.5; cursor: default; transform: none; }

/* === CURRICULUM PAGE === */
.learn-hero {
  background: var(--primary);
  padding: 48px 0;
  color: #fff;
}
.learn-hero h1 {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 12px;
  letter-spacing: -0.5px;
}
.learn-hero p { font-size: 16px; color: rgba(255,255,255,0.75); max-width: 560px; }
.learn-hero .btn-signin {
  display: inline-block;
  margin-top: 20px;
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-size: 15px;
  text-decoration: none;
  transition: var(--transition);
}
.learn-hero .btn-signin:hover { background: #ffbe4d; text-decoration: none; }

.curriculum-section { padding: 48px 0; }
.curriculum-section h2 {
  font-size: 26px;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.3px;
}
.curriculum-section .section-sub {
  font-size: 15px;
  color: var(--text-light);
  margin-bottom: 32px;
}
.cert-list { display: flex; flex-direction: column; gap: 12px; }
.cert-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 22px;
  background: var(--bg);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-lg);
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
  color: var(--text);
}
.cert-item:hover { border-color: var(--accent); box-shadow: var(--card-shadow-hover); transform: translateX(4px); text-decoration: none; }
.cert-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  flex-shrink: 0;
}
.cert-info { flex: 1; }
.cert-title { font-size: 16px; font-weight: 600; color: var(--text); }
.cert-meta { font-size: 13px; color: var(--text-light); margin-top: 2px; }
.cert-arrow { color: var(--text-muted); font-size: 18px; }

.challenge-box {
  background: linear-gradient(135deg, var(--primary) 0%, #1a1a4e 100%);
  border-radius: var(--radius-lg);
  padding: 36px 40px;
  color: #fff;
  margin-bottom: 48px;
}
.challenge-box h2 { font-size: 24px; font-weight: 700; margin-bottom: 10px; }
.challenge-box p { color: rgba(255,255,255,0.75); margin-bottom: 24px; font-size: 15px; }
.challenge-links { display: flex; gap: 12px; flex-wrap: wrap; }
.btn-challenge {
  padding: 10px 22px;
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: var(--transition);
}
.btn-challenge.primary { background: var(--accent); color: var(--primary); }
.btn-challenge.primary:hover { background: #ffbe4d; text-decoration: none; }
.btn-challenge.secondary { background: rgba(255,255,255,0.1); color: #fff; border: 1.5px solid rgba(255,255,255,0.25); }
.btn-challenge.secondary:hover { background: rgba(255,255,255,0.18); text-decoration: none; }

.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}
.resource-card {
  background: var(--bg-light);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.resource-card h3 { font-size: 16px; font-weight: 700; margin-bottom: 14px; color: var(--text); }
.resource-link {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
  color: var(--link);
  text-decoration: none;
  transition: var(--transition);
}
.resource-link:last-child { border-bottom: none; }
.resource-link:hover { color: var(--primary); text-decoration: underline; }
.resource-link::before { content: '→'; font-size: 12px; color: var(--accent); }

/* === DONATE PAGE === */
.donate-hero {
  background: var(--primary);
  padding: 64px 0;
  color: #fff;
  text-align: center;
}
.donate-hero h1 {
  font-size: 40px;
  font-weight: 800;
  margin-bottom: 16px;
  letter-spacing: -0.8px;
}
.donate-hero p {
  font-size: 17px;
  color: rgba(255,255,255,0.75);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.donation-form-section { padding: 48px 0; }
.donation-card {
  max-width: 540px;
  margin: 0 auto;
  background: var(--bg);
  border-radius: var(--radius-lg);
  box-shadow: 0 8px 40px rgba(10,10,35,0.12);
  border: 1px solid var(--border);
  overflow: hidden;
}
.donation-card-header {
  background: var(--primary);
  padding: 24px 32px;
  color: #fff;
}
.donation-card-header h2 { font-size: 22px; font-weight: 700; }
.donation-card-header p { font-size: 14px; color: rgba(255,255,255,0.65); margin-top: 4px; }
.donation-card-body { padding: 28px 32px; }

.amount-tabs {
  display: flex;
  gap: 10px;
  margin-bottom: 24px;
}
.amount-btn {
  flex: 1;
  padding: 12px 8px;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
  background: var(--bg);
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font);
}
.amount-btn:hover { border-color: var(--accent); }
.amount-btn.active {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--primary);
}

.donation-desc {
  background: var(--bg-light);
  border-radius: var(--radius);
  padding: 14px 18px;
  font-size: 14px;
  color: var(--text);
  margin-bottom: 24px;
  border-left: 3px solid var(--accent);
  min-height: 52px;
  transition: var(--transition);
}

.btn-donate {
  display: block;
  width: 100%;
  padding: 16px;
  background: var(--accent);
  color: var(--primary);
  font-size: 17px;
  font-weight: 800;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  font-family: var(--font);
  transition: var(--transition);
  letter-spacing: -0.2px;
}
.btn-donate:hover { background: #ffbe4d; transform: translateY(-1px); }
.donate-sublabel {
  text-align: center;
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 12px;
}
.donate-sublabel a { color: var(--link); }

.benefits-section { background: var(--bg-light); padding: 56px 0; }
.benefits-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 32px;
  letter-spacing: -0.3px;
}
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
}
.benefit-icon { font-size: 24px; flex-shrink: 0; }
.benefit-text { font-size: 15px; color: var(--text); line-height: 1.5; }

.initiatives-section { padding: 56px 0; }
.initiatives-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 32px;
  letter-spacing: -0.3px;
}
.initiatives-list { display: flex; flex-direction: column; gap: 12px; }
.initiative-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 18px 22px;
  background: var(--bg-light);
  border-radius: var(--radius);
}
.initiative-bullet {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
  margin-top: 6px;
}
.initiative-text { font-size: 15px; color: var(--text); }

.stats-section { background: var(--primary); padding: 56px 0; color: #fff; }
.stats-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 40px;
  letter-spacing: -0.3px;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.stat-item {
  background: rgba(255,255,255,0.07);
  border-radius: var(--radius-lg);
  padding: 24px;
  border: 1px solid rgba(255,255,255,0.1);
}
.stat-number {
  font-size: 36px;
  font-weight: 800;
  color: var(--accent);
  letter-spacing: -1px;
  margin-bottom: 6px;
}
.stat-label { font-size: 14px; color: rgba(255,255,255,0.7); line-height: 1.4; }

/* === FAQ ACCORDION === */
.faq-section { padding: 56px 0; background: var(--bg-light); }
.faq-section h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 32px;
  letter-spacing: -0.3px;
}
.faq-list { display: flex; flex-direction: column; gap: 8px; max-width: 800px; }
.faq-item {
  background: var(--bg);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: var(--transition);
}
.faq-item.open { border-color: var(--accent); }
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  cursor: pointer;
  gap: 16px;
  background: none;
  width: 100%;
  text-align: left;
  font-family: var(--font);
}
.faq-question-text {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  line-height: 1.4;
}
.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text);
  font-size: 18px;
  flex-shrink: 0;
  transition: var(--transition);
  font-weight: 300;
}
.faq-item.open .faq-icon { background: var(--accent); color: var(--primary); transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-answer-inner { padding: 0 20px 18px; font-size: 14px; color: var(--text-light); line-height: 1.7; }
.faq-item.open .faq-answer { max-height: 400px; }

/* === TAG PAGE === */
.tag-header { padding: 40px 0 24px; }
.tag-title {
  display: flex;
  align-items: baseline;
  gap: 16px;
  flex-wrap: wrap;
}
.tag-title h1 {
  font-size: 36px;
  font-weight: 800;
  color: var(--text);
  letter-spacing: -0.8px;
}
.tag-count {
  font-size: 16px;
  color: var(--text-light);
  font-weight: 400;
}

.popular-tags-section { padding: 16px 0 32px; }
.popular-tags-label {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--text-muted);
  margin-bottom: 12px;
}
.popular-tags-scroll {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 8px;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}
.popular-tags-scroll::-webkit-scrollbar { height: 4px; }
.popular-tags-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
.popular-tag-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  background: var(--bg-light);
  border: 1.5px solid var(--border);
  white-space: nowrap;
  text-decoration: none;
  transition: var(--transition);
  flex-shrink: 0;
}
.popular-tag-item:hover { border-color: var(--primary); background: var(--primary); text-decoration: none; }
.popular-tag-item:hover .ptag-name,
.popular-tag-item:hover .ptag-count { color: #fff; }
.ptag-name { font-size: 13px; font-weight: 600; color: var(--text); }
.ptag-count { font-size: 12px; color: var(--text-muted); }

/* === FOOTER === */
.site-footer {
  background: var(--primary);
  color: rgba(255,255,255,0.7);
  padding: 48px 0 32px;
}
.footer-mission {
  font-size: 14px;
  line-height: 1.7;
  max-width: 640px;
  margin-bottom: 36px;
  border-left: 3px solid var(--accent);
  padding-left: 16px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  margin-bottom: 36px;
}
.footer-col h3 {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: rgba(255,255,255,0.45);
  margin-bottom: 14px;
}
.footer-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.footer-tag {
  color: rgba(255,255,255,0.65);
  font-size: 13px;
  text-decoration: none;
  transition: var(--transition);
}
.footer-tag:hover { color: var(--accent); text-decoration: none; }
.footer-tag::after { content: ' ·'; margin-right: 2px; }
.footer-tag:last-child::after { content: ''; }
.footer-links { display: flex; flex-wrap: wrap; gap: 6px; }
.footer-links a {
  color: rgba(255,255,255,0.65);
  font-size: 13px;
  text-decoration: none;
  transition: var(--transition);
}
.footer-links a:hover { color: rgba(255,255,255,0.9); text-decoration: underline; }
.footer-links a::after { content: ' ·'; margin-right: 2px; }
.footer-links a:last-child::after { content: ''; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}
.footer-logo { display: flex; align-items: center; gap: 8px; text-decoration: none; }
.footer-logo .logo-icon { width: 28px; height: 28px; font-size: 14px; }
.footer-logo .logo-text { font-size: 15px; }
.footer-copy { font-size: 13px; }

/* === UTILITIES === */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

/* === RESPONSIVE === */
@media (max-width: 900px) {
  .articles-grid { grid-template-columns: repeat(2, 1fr); }
  .resources-grid { grid-template-columns: 1fr 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .featured-card { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 220px; }
  .featured-title { font-size: 20px; }
  .footer-grid { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  :root { --header-h: 56px; }
  .container { padding: 0 16px; }
  .search-bar { display: none; }
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .articles-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .challenge-links { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .donate-hero h1 { font-size: 28px; }
  .learn-hero h1 { font-size: 24px; }
  .featured-content { padding: 20px; }
  .donation-card-body { padding: 20px; }
  .donation-card-header { padding: 18px 20px; }
  .amount-tabs { gap: 6px; }
  .amount-btn { font-size: 16px; }
  .tag-title h1 { font-size: 26px; }
}

